<?php
declare(strict_types=1);require_once __DIR__.'/common.php';$user=qa_require_user();$pdo=db();$id=(int)($_GET['id']??$_POST['id']??0);$st=$pdo->prepare('SELECT * FROM qa_questions WHERE id=? AND user_id=?');$st->execute([$id,(int)$user['id']]);$q=$st->fetch();if(!$q)exit('Question not found or not yours.');$error='';if($_SERVER['REQUEST_METHOD']==='POST'){try{qa_post();$title=trim((string)$_POST['title']);$desc=trim((string)$_POST['description']);if($title===''||$desc==='')throw new RuntimeException('Title and description required.');$pdo->prepare('UPDATE qa_questions SET title=?,description=?,code_snippet=?,code_language=? WHERE id=?')->execute([$title,$desc,trim((string)($_POST['code_snippet']??''))?:null,trim((string)($_POST['code_language']??''))?:null,$id]);$file=qa_image_upload();if($file)qa_save_attachment($pdo,$id,null,(int)$user['id'],$file);qa_redirect('view.php?id='.$id);}catch(Throwable $e){$error=$e->getMessage();}}qa_header('Edit Question');?><section class="panel"><h3>Edit question</h3><?php if($error):?><p class="error"><?=e($error)?></p><?php endif?><form method="post" enctype="multipart/form-data"><input type="hidden" name="csrf" value="<?=e(csrf())?>"><input type="hidden" name="id" value="<?=$id?>"><label>Title</label><input name="title" value="<?=e($q['title'])?>" required><label>Description</label><textarea name="description" required><?=e($q['description'])?></textarea><label>Code</label><textarea name="code_snippet"><?=e((string)$q['code_snippet'])?></textarea><label>Language</label><input name="code_language" value="<?=e((string)$q['code_language'])?>"><label>Add image</label><input type="file" name="image" accept="image/jpeg,image/png,image/gif,image/webp"><button>Save changes</button></form></section><?php qa_footer();
